18	public sealed class FabricaApi : WebApplicationFactory<Program>
19	{
20	    public const string IpPorDefecto = "10.0.0.1";
21	
22	    private readonly IReadOnlyDictionary<string, string?> _configuracion;
23	    private readonly IBaseConocimiento? _conocimiento;
24	    private readonly bool _reemplazarLlm;
25	    private readonly HttpMessageHandler? _manejadorHttp;
26	
27	    public FabricaApi(
28	        ApiAcademicaDoble? api = null,
29	        ClienteLlmDoble? llm = null,
30	        IBaseConocimiento? conocimiento = null,
31	        IReadOnlyDictionary<string, string?>? configuracion = null,
32	        bool reemplazarLlm = true,
33	        HttpMessageHandler? manejadorHttp = null,
34	        bool conocimientoReal = false)
35	    {
36	        Api = api ?? new ApiAcademicaDoble();
37	        Llm = llm ?? ClienteLlmDoble.Texto("Respuesta de prueba.");
38	        _conocimiento = ElegirConocimiento(conocimiento, conocimientoReal);
39	        _configuracion = configuracion ?? SinConfiguracion;
40	        _reemplazarLlm = reemplazarLlm;
41	        _manejadorHttp = manejadorHttp;
42	    }
