46	    public ApiAcademicaDoble Api { get; }
47	
48	    public ClienteLlmDoble Llm { get; }
49	
50	    public AuditoriaEnMemoria Auditoria { get; } = new();
51	
52	    public RelojControlado Reloj { get; } = new();
53	
54	    public CapturaLogs Logs { get; } = new();
55	
56	    private static IBaseConocimiento? ElegirConocimiento(IBaseConocimiento? conocimiento, bool real) =>
57	        real ? null : conocimiento ?? BaseConocimientoFalsa.Vigente();
58	
59	    public static Dictionary<string, string?> Precios(string entrada, string salida) =>
60	        new Dictionary<string, string?> { ["LLM_PRECIO_ENTRADA"] = entrada, ["LLM_PRECIO_SALIDA"] = salida };
61	
62	    public async Task<RespuestaApi> PreguntarAsync(string rol, string id, string pregunta, string ip = IpPorDefecto, IReadOnlyDictionary<string, string>? encabezados = null)
63	    {
64	        var cuerpo = JsonSerializer.Serialize(new { pregunta, usuario = new { rol, id } });
65	        return await EnviarAsync(HttpMethod.Post, "/api/asistente/preguntar", cuerpo, ip, encabezados);
66	    }
67	
68	    public Task<RespuestaApi> PreguntarEstudianteAsync(string id, string pregunta, string ip = IpPorDefecto) =>
69	        PreguntarAsync("estudiante", id, pregunta, ip);
70	
71	    public Task<RespuestaApi> PreguntarCoordinadorAsync(string id, string pregunta, string ip = IpPorDefecto) =>
72	        PreguntarAsync("coordinador", id, pregunta, ip);
73	
74	    public async Task<RespuestaApi> EnviarAsync(HttpMethod metodo, string ruta, string? cuerpo, string ip = IpPorDefecto, IReadOnlyDictionary<string, string>? encabezados = null)
75	    {
76	        using var cliente = CreateClient();
